// TH15 Extra Stage 7 道中 w03: st07.ecl.txt MainSub02 (1149-1161)
// GirlD02 / GirlD02_at / GirlD02_at2 (711-765).
// 卡帧 0 = MainSub02 入口；+120 为训练外壳开场缓冲，源内 wait 全部保留。
const TIME_LIMIT: int = 1524;
const OPENING_BUFFER: int = 120;

// TH15 type 20, color 6 (touhou-bullets.ecl: TH15_OVAL, 基础半径 7).
const TH15_OVAL: int = 672;
const OVAL_COLOR: int = 6;

// GirlD02_at2 的 VELTIME: a=120, r=3.0, s=-999999(保留方向).
// 标量速度 2.0 -> 3.0 / 120 帧，方向不变；用极坐标沿向加速度表达。
xformdef GIRL_VELTIME(unused: int) {
    set_accel(1fx/120fx);
    wait(120);
    set_accel(0fx);
}

// GirlD02_at2 单次 etOn：etAim(0,0) 自机狙扇形，
// n=6 -> ±10/±30/±50 度；n=5 -> 0/±20/±40 度，delta=20 度。
sub girl_volley(n: int) {
    var aim: angle = aim_player();
    for i in 0..n {
        var off: int = 0;
        if n == 6 {
            off = 1820 + (i/2)*3641;
            if i % 2 != 0 { off = -off; }
        } else {
            if i != 0 {
                off = ((i+1)/2)*3641;
                if i % 2 == 0 { off = -off; }
            }
        }
        var a: angle = aim + (off as angle);
        // EX 0x2 ANIM a=1 的出生退位移 position -= 4*velocity：
        // 初速 2.0，故沿弹道后退 8px；出生动画本身按已批准口径省略。
        var bx: fx = $self_x - 8fx*cos(a);
        var by: fx = $self_y - 8fx*sin(a);
        _ = fire(TH15_OVAL, OVAL_COLOR, bx, by, 2fx, a, GIRL_VELTIME(0), none);
    }
}

// GirlD02_at2 @742-765: $A=32, 每轮 6 发 + wait20 + 5 发 + wait20.
async sub girl_fire() {
    for k in 0..32 {
        girl_volley(6);
        wait(20);
        girl_volley(5);
        wait(20);
    }
}

// GirlD02_at @724-740. 右侧 enmCreateM 的子镜像位=1：
// 普通 moveVel/moveVelTime 的角度按 x 取负（180-angle），发弹角不套镜像。
async sub girl_d02(mirror: int) {
    set_invuln(65535);
    set_hitbox(8fx);   // 源 setHitbox(16,16) 普通圆取首值一半
    set_hurtbox(12fx); // 源 setHurtbox(24,24)
    move_vel(0, 90deg, 3fx, EASE_LINEAR); // moveVel(pi/2, 3.0)
    var turn1: angle = 78.75deg;          // rad 1.3744467
    if mirror != 0 { turn1 = 101.25deg; }
    move_vel(60, turn1, 0fx, EASE_QUAD_IN); // moveVelTime(60, mode1, ...)
    wait(60);
    spawn girl_fire();                      // @GirlD02_at2() async, 源 t=60
    wait(120);
    var turn2: angle = 11.25deg;            // rad 0.19634955
    if mirror != 0 { turn2 = 168.75deg; }
    move_vel(60, turn2, 1fx, EASE_LINEAR);  // moveVelTime(60, mode0, ...)
    // 源随后 wait(1000) 无限循环；敌保持直到出界回收。
    loop { wait(1); }
}

// MainSub02 @1149-1161: wait2, 左右一对；wait160；再一对；wait160；第三对。
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(2);
    _ = spawn_enemy(-92fx, -48fx, 1000, 0, 0, 0, girl_d02(0));   // enmCreate
    _ = spawn_enemy(164fx, -48fx, 1000, 0, 0, 0, girl_d02(1));   // enmCreateM
    wait(160);
    _ = spawn_enemy(-182fx, -48fx, 1000, 0, 0, 0, girl_d02(0));
    _ = spawn_enemy(74fx, -48fx, 1000, 0, 0, 0, girl_d02(1));
    wait(160);
    _ = spawn_enemy(-32fx, -48fx, 1000, 0, 0, 0, girl_d02(0));
    _ = spawn_enemy(224fx, -48fx, 1000, 0, 0, 0, girl_d02(1));
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
